package main

import (
	"context"
	"go.opentelemetry.io/otel"
	"github.com/uptrace/uptrace-go/uptrace"
)

func main() {
	ctx := context.Background()

	// Configure OpenTelemetry with Uptrace
	// DSN is read from UPTRACE_DSN env var automatically
	uptrace.ConfigureOpentelemetry(
		uptrace.WithServiceName("go-service"),
		uptrace.WithServiceVersion("1.0.0"),
		uptrace.WithDeploymentEnvironment("production"),
	)
	// Flush buffered spans before exit
	defer uptrace.Shutdown(ctx)

	tracer := otel.Tracer("my-tracer")
	_, span := tracer.Start(ctx, "main-operation")
	defer span.End()
}

