use opentelemetry::trace::TraceError;
use opentelemetry::{global, trace::Tracer};
use opentelemetry_otlp::WithExportConfig;
use opentelemetry_sdk::runtime;

fn init_tracer() -> Result<(), TraceError> {
    let endpoint = std::env::var("OTEL_EXPORTER_OTLP_ENDPOINT")
        .unwrap_or_else(|_| "https://otlp.uptrace.dev:4317".to_string());
    let dsn = std::env::var("OTEL_EXPORTER_OTLP_HEADERS")
        .unwrap_or_default();

    opentelemetry_otlp::new_pipeline()
        .tracing()
        .with_exporter(
            opentelemetry_otlp::new_exporter()
                .tonic()
                .with_endpoint(endpoint)
                .with_metadata({
                    let mut map = tonic::metadata::MetadataMap::new();
                    map.insert("uptrace-dsn", dsn.parse().unwrap());
                    map
                }),
        )
        .with_trace_config(
            opentelemetry_sdk::trace::Config::default()
                .with_resource(opentelemetry_sdk::Resource::new(vec![
                    opentelemetry::KeyValue::new("service.name", "rust-service"),
                ])),
        )
        .install_batch(runtime::Tokio)?;
    Ok(())
}

#[tokio::main]
async fn main() {
    init_tracer().expect("Failed to initialize tracer");
    let tracer = global::tracer("my-tracer");
    tracer.in_span("main-operation", |_cx| {
        println!("Traced operation executing...");
    });
    global::shutdown_tracer_provider();
}

from fastapi import FastAPI
import uptrace
from opentelemetry.instrumentation.fastapi import FastAPIInstrumentor

