import (
	"context"
	"database/sql"

	"github.com/uptrace/opentelemetry-go-extra/otelsql"
	"github.com/uptrace/uptrace-go/uptrace"
	semconv "go.opentelemetry.io/otel/semconv/v1.21.0"
	_ "github.com/go-sql-driver/mysql"
)

func main() {
	ctx := context.Background()
	uptrace.ConfigureOpentelemetry(
		uptrace.WithServiceName("sql-service"),
		uptrace.WithServiceVersion("1.0.0"),
	)
	defer uptrace.Shutdown(ctx)

	// Wrap the driver with OpenTelemetry
	db, err := otelsql.Open("mysql", "root:@tcp(localhost:3306)/mydb",
		otelsql.WithAttributes(semconv.DBSystemMySQL),
		otelsql.WithDBName("mydb"),
	)
	if err != nil {
		panic(err)
	}
	defer db.Close()

	// All queries are now automatically traced
	row := db.QueryRowContext(ctx, "SELECT 1")
	_ = row
}

package main

import (
	"context"

	"github.com/uptrace/opentelemetry-go-extra/otelgorm"
	"github.com/uptrace/uptrace-go/uptrace"
	"gorm.io/driver/postgres"
	"gorm.io/gorm"
)

type User struct {
	gorm.Model
	Name string
}

func main() {
	ctx := context.Background()
	uptrace.ConfigureOpentelemetry(
		uptrace.WithServiceName("gorm-service"),
		uptrace.WithServiceVersion("1.0.0"),
	)
	defer uptrace.Shutdown(ctx)

	dsn := "host=localhost user=myuser password=mypassword dbname=mydb port=5432 sslmode=disable"
	db, err := gorm.Open(postgres.Open(dsn), &gorm.Config{})
	if err != nil {
		panic(err)
	}

	// Add OpenTelemetry plugin — all queries are now traced
	if err := db.Use(otelgorm.NewPlugin()); err != nil {
		panic(err)
	}

	db.AutoMigrate(&User{})

	// Traced query
	var users []User
	db.WithContext(ctx).Find(&users)
}

