	ctx := context.Background()
	uptrace.ConfigureOpentelemetry(
		uptrace.WithServiceName("go-lambda-service"),
		uptrace.WithServiceVersion("1.0.0"),
	)
	defer uptrace.Shutdown(ctx)

	// Wrap the handler with OpenTelemetry instrumentation
	lambda.Start(otellambda.InstrumentHandler(handler))
}

// handler.js
const uptrace = require('@uptrace/node');
const { AwsLambdaInstrumentation } = require('@opentelemetry/instrumentation-aws-lambda');

const sdk = uptrace.configureOpentelemetry({
  // dsn: process.env.UPTRACE_DSN,
  serviceName: process.env.OTEL_SERVICE_NAME || 'node-lambda-service',
  instrumentations: [
    new AwsLambdaInstrumentation({
      requestHook: (span, { event }) => {
        span.setAttribute('event.source', event.source || 'unknown');
      },
    }),
  ],
});

sdk.start();

exports.handler = async (event, context) => {
  return {
    statusCode: 200,
    body: JSON.stringify({ message: 'Hello from Uptrace Lambda!' }),
  };
};

