package main

import (
	"context"

	"github.com/uptrace/opentelemetry-go-extra/otelzap"
	"github.com/uptrace/uptrace-go/uptrace"
	"go.opentelemetry.io/otel"
	"go.uber.org/zap"
)

func main() {
	ctx := context.Background()
	uptrace.ConfigureOpentelemetry(
		uptrace.WithServiceName("zap-service"),
	)
	defer uptrace.Shutdown(ctx)

	// Create Zap logger with OpenTelemetry bridge
	logger := otelzap.New(zap.NewExample())
	defer logger.Sync()

	// Make it global
	undo := otelzap.ReplaceGlobals(logger)
	defer undo()

	tracer := otel.Tracer("my-tracer")
	ctx, span := tracer.Start(ctx, "main-operation")
	defer span.End()

	// Logs will include trace_id and span_id
	logger.Ctx(ctx).Info("Hello from Zap + Uptrace!", zap.String("key", "value"))
}
